using Apogeu.BuildingBlocks.Contracts;

namespace Apogeu.Betting.Features.Hubs;

/// <summary>Argument of <c>PlaceBet</c> (SPEC-0022 §6).</summary>
/// <param name="ClientBetId">Idempotency key generated by the client: repeating it returns the original <see cref="BetAccepted"/>.</param>
/// <param name="Panel">Panel 1 or 2.</param>
/// <param name="Amount">Amount, at most 2 decimal places.</param>
/// <param name="AutoCashOut">Optional automatic cash-out, between 1.01x and the room's cap.</param>
public sealed record PlaceBetRequest(Guid ClientBetId, int Panel, Money Amount, Multiplier? AutoCashOut);
